use strict;use warnings;use JSON::PP;use Digest::SHA qw(sha256_hex);use File::Basename qw(dirname);chdir dirname(__FILE__).'/..' or die $!;
sub readf{open my $f,'<',$_[0] or die $!;local $/;return <$f>}
sub prefix_ids {my($s,$prefix)=@_;my %ids=map {$_=>"$prefix$_"} ($s=~/\bid="([^"]+)"/g);for my $id(keys %ids){my $new=$ids{$id};$s=~s/\bid="\Q$id\E"/id="$new"/g;$s=~s/url\(#\Q$id\E\)/url(#$new)/g;$s=~s/((?:xlink:)?href=")#\Q$id\E"/$1#$new"/g;}return $s;}
my $m=decode_json(readf('manifest.json'));my @checks;my $total=0;for my $f(@{$m->{files}}){my $s=readf('runtime/'.$f->{url});die 'bytes/hash mismatch' unless length($s)==$f->{bytes} && sha256_hex($s) eq $f->{sha256};die 'unsafe external reference' if $s =~ /(?:<script|https?:\/\/(?!www.w3.org\/2000\/svg)|href=|<image)/;die 'missing svg wrapper' unless $s=~ /^<svg / && $s=~ m!</svg>$!; $total+=length $s;push @checks,{url=>$f->{url},bytesAndHash=>'pass',wrapperAndExternalReferenceScan=>'pass'};}
my $default=0;for(@{$m->{files}}){$default+=$_->{bytes} if $_->{url}=~m!^(faces/|bodies/default)!}die 'budget' unless $default<=250000 && $total<=2000000;
my $r={checks=>\@checks,totalBytes=>$total,defaultAndFacesBytes=>$default,notChecked=>['XML parser unavailable: wrapper scan is not parsing','No local raster renderer: painted extents/alpha not measured','No browser/game decoding, face alignment, 80px/DPR or portrait/landscape check','Adaptation appearance awaits review'],status=>'static inventory passed; visual and runtime review pending'};open my $out,'>','review/static-checks.json';print $out JSON::PP->new->canonical->pretty->encode($r);close $out;
my $html='<!doctype html><meta charset="utf-8"><title>Cat Tower production 02 review</title><style>body{margin:16px;font:16px system-ui;background:#fff7e8;color:#42362a}svg{max-width:100%;height:auto}p{max-width:70ch}</style><p>Review draft: native vector interpretation, not direct generated transparent sprites. Simplified texture/scenery needs appearance review. Not runtime-approved.</p>'.readf('review/contact-sheet.svg');
$html.='<h2>80px logical body-width alignment samples</h2><p>Source canvas renders at 98.46px; logical body is 80px. Face canvas renders at 36px (0.45 logical width). Browser/device validation pending.</p><div style="display:flex;flex-wrap:wrap;gap:16px">';
for my $f(@{$m->{faces}}){my $b=readf('runtime/bodies/default.svg');$b=~s/^<svg [^>]*>//;$b=~s!</svg>$!!;$b=prefix_ids($b,"sample-".$f->{id}."-");my $face=readf('runtime/'.$f->{url});$face=~s/^<svg [^>]*>//;$face=~s!</svg>$!!;$face=prefix_ids($face,"face-".$f->{id}."-");$html.='<div><svg xmlns="http://www.w3.org/2000/svg" width="98.4615" height="73.8462" viewBox="0 0 512 384">'.$b.'<svg x="162.4" y="115.225806" width="187.2" height="187.2" viewBox="0 0 128 128">'.$face.'</svg></svg><p>'.$f->{id}.'</p></div>';}$html.='</div>';open my $h,'>','review/preview.html';print $h $html;close $h;print JSON::PP->new->encode($r);
